from bcommon import *
S = 'English'; REL = ('language/', 'English words and activities')
V = {'apple': '1f34e', 'banana': '1f34c', 'cat': '1f431', 'dog': '1f436', 'fish': '1f41f', 'egg': 'x_egg', 'sun': '2600', 'moon': '1f319', 'star': '2b50', 'book': 'i_book', 'ball': '26bd', 'bee': '1f41d', 'tree': '1f333', 'car': '1f697', 'bird': '1f426', 'cow': '1f404', 'duck': '1f986', 'hand': 'x_hand', 'pen': 'i_pencil', 'rose': '1f339', 'lemon': '1f34b', 'grapes': '1f347', 'carrot': '1f955', 'bus': '1f68c'}
def pairs(ws): return [(w, w, V[w]) for w in ws]
def vq(w, ds, say=True): return Q('What is this?', w, ds, f'This is a {w}.' if w[0] not in 'aeiou' else f'This is an {w}.', img=V[w], say=w if say else None)
